package com.commutemate.ride;
import com.commutemate.common.TenantContextHolder; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.util.List; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/locations") public class LocationAdminController { private final LocationRepository repo; public LocationAdminController(LocationRepository repo){this.repo=repo;} public record CreateLocation(@NotBlank String name,double latitude,double longitude,@NotBlank String timezone){} @GetMapping public List<Location> all(){var c=TenantContextHolder.getRequired(); return repo.findAllByTenantIdAndActiveTrueOrderByName(c.tenantId());} @PostMapping public Location create(@Valid @RequestBody CreateLocation r){var c=TenantContextHolder.getRequired(); if(!c.role().equals("TENANT_ADMIN")&&!c.role().equals("MOBILITY_ADMIN")) throw new SecurityException("Admin role required"); return repo.save(new Location(c.tenantId(),r.name(),r.latitude(),r.longitude(),r.timezone()));}}
